#!/bin/bash\n\n# ===================================\n# Script de build du projet Mini-ERP\n# ===================================\n#\n# Ce script construit le projet dans le bon ordre:\n# 1. Module rmi-common (dépendance)\n# 2. Services (qui dépendent de rmi-common)\n#\n\nset -e\n\necho \"\"\necho \"====================================================================\"\necho \"             Mini-ERP - Build Script\"\necho \"====================================================================\"\necho \"\"\n\necho \"Step 1: Construire le module RMI commun (rmi-common)...\"\necho \"\"\ncd rmi-common\nmvn clean install\ncd ..\necho \"✅ rmi-common construit avec succès\"\necho \"\"\n\necho \"Step 2: Construire les services...\"\necho \"\"\n\necho \"📦 Construction du stock-service...\"\ncd stock-service\nmvn clean install\ncd ..\necho \"✅ stock-service construit\"\necho \"\"\n\necho \"📦 Construction du ventes-service...\"\ncd ventes-service\nmvn clean install\ncd ..\necho \"✅ ventes-service construit\"\necho \"\"\n\necho \"📦 Construction du finance-service...\"\ncd finance-service\nmvn clean install\ncd ..\necho \"✅ finance-service construit\"\necho \"\"\n\necho \"📦 Construction du api-gateway...\"\ncd api-gateway\nmvn clean install\ncd ..\necho \"✅ api-gateway construit\"\necho \"\"\n\necho \"====================================================================\"\necho \"✅ BUILD TERMINÉ AVEC SUCCÈS!\"\necho \"====================================================================\"\necho \"\"\necho \"Tous les modules ont été construits avec succès.\"\necho \"Les erreurs dans l'IDE devraient maintenant disparaître.\"\necho \"\"\necho \"Vous pouvez maintenant:\"\necho \"  • Démarrer les services: bash start-with-rmi.sh docker\"\necho \"  • Ou relancer le projet dans votre IDE\"\necho \"\"\n"